"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Scale SEAL Leaderboards: Frontier Model Performance Across 20+ Benchmarks";

// ── Color palette ──────────────────────────────────────────────────
// Deep navy as dominant bg for title/closing, off-white for content
const C = {
  navy:    "0F1F3D",   // dominant dark
  navy2:   "162848",   // slightly lighter dark
  ice:     "E8EEF7",   // light content bg
  white:   "FFFFFF",
  accent:  "3B82F6",   // blue accent
  openai:  "10A37F",   // OpenAI green
  google:  "4285F4",   // Google blue
  anthro:  "CC785C",   // Anthropic terracotta
  muse:    "8B5CF6",   // Muse Spark purple
  red:     "EF4444",
  amber:   "F59E0B",
  slate:   "64748B",
  slate2:  "94A3B8",
  darkTxt: "1E293B",
  midTxt:  "475569",
};

const TITLE_FONT = "Calibri";
const BODY_FONT  = "Calibri";

// ── Helpers ─────────────────────────────────────────────────────────
function makeShadow() {
  return { type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.12 };
}

function bgRect(slide, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 5.625,
    fill: { color },
    line: { color, width: 0 },
  });
}

function slideHeader(slide, title, light = false) {
  const txtColor = light ? C.white : C.darkTxt;
  const barColor = light ? C.accent : C.accent;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.78,
    fill: { color: light ? C.navy : C.ice },
    line: { color: light ? C.navy : C.ice, width: 0 },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.78, w: 10, h: 0.045,
    fill: { color: barColor },
    line: { color: barColor, width: 0 },
  });
  slide.addText(title, {
    x: 0.45, y: 0.06, w: 9.1, h: 0.66,
    fontFace: TITLE_FONT, fontSize: 22, bold: true,
    color: txtColor, align: "left", valign: "middle", margin: 0,
  });
}

function slideFooter(slide, light = false) {
  const barColor = light ? C.navy2 : C.ice;
  const txtColor = light ? C.slate2 : C.slate;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.38, w: 10, h: 0.245,
    fill: { color: barColor },
    line: { color: barColor, width: 0 },
  });
  slide.addText("Scale SEAL Leaderboards  |  scale.com/leaderboard", {
    x: 0.3, y: 5.39, w: 9.4, h: 0.21,
    fontFace: BODY_FONT, fontSize: 9, color: txtColor, align: "left", valign: "middle", margin: 0,
  });
}

function labChip(slide, lab, x, y) {
  const colors = {
    "OpenAI":   C.openai,
    "Google":   C.google,
    "Anthropic":C.anthro,
    "Muse Spark": C.muse,
  };
  const col = colors[lab] || C.slate;
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 1.25, h: 0.28,
    fill: { color: col },
    line: { color: col, width: 0 },
  });
  slide.addText(lab, {
    x, y, w: 1.25, h: 0.28,
    fontFace: BODY_FONT, fontSize: 9.5, bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0,
  });
}

// ═══════════════════════════════════════════════════════════════════
// Slide 1 – Title
// ═══════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  bgRect(s, C.navy);

  // Diagonal accent band
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 0, w: 3.2, h: 5.625,
    fill: { color: C.navy2 },
    line: { color: C.navy2, width: 0 },
  });

  // Accent stripe
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 0, w: 0.05, h: 5.625,
    fill: { color: C.accent },
    line: { color: C.accent, width: 0 },
  });

  // Scale "dot" label
  s.addText("SCALE SEAL LEADERBOARDS", {
    x: 0.55, y: 0.85, w: 6.0, h: 0.32,
    fontFace: TITLE_FONT, fontSize: 10, bold: true,
    color: C.accent, align: "left", charSpacing: 3, margin: 0,
  });

  s.addText("Frontier Model Performance\nAcross 20+ AI Benchmarks", {
    x: 0.55, y: 1.28, w: 6.0, h: 1.9,
    fontFace: TITLE_FONT, fontSize: 38, bold: true,
    color: C.white, align: "left", valign: "top", margin: 0,
  });

  s.addText("A comparative analysis of 100+ models from OpenAI, Google, Anthropic,\nMeta, and new entrants across Agentic, Frontier, Safety, and Multimodal benchmarks.", {
    x: 0.55, y: 3.35, w: 6.0, h: 0.9,
    fontFace: BODY_FONT, fontSize: 13, color: C.slate2,
    align: "left", valign: "top", margin: 0,
