// ═══════════════════════════════════════════════════════════════════
// Slide 7 – Lab Competitive Landscape (heatmap matrix)
// ═══════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  bgRect(s, C.ice);
  slideHeader(s, "OpenAI, Google, and Anthropic Each Claim #1 Across Different Domains");
  slideFooter(s);

  s.addText("Which lab's model ranks #1 on each benchmark? Heatmap view — no single lab wins everywhere.", {
    x: 0.45, y: 0.88, w: 9.1, h: 0.28,
    fontFace: BODY_FONT, fontSize: 11, color: C.midTxt, align: "left", margin: 0,
  });

  const labColors = {
    "OpenAI":     { fill: "E8F5F0", text: C.openai },
    "Google":     { fill: "EBF3FE", text: C.google },
    "Anthropic":  { fill: "FFF3EE", text: C.anthro },
    "Muse Spark": { fill: "F3EEFF", text: C.muse },
  };

  const matrixData = [
    // [Domain, Benchmark, #1 Lab, #1 Model, Score]
    ["AGENTIC",   "SWE Atlas – Test Writing",        "OpenAI",     "GPT-5.4-xHigh (Codex CLI)",    "44.36"],
    ["AGENTIC",   "SWE Atlas – Codebase QnA",        "OpenAI",     "GPT-5.4-xHigh (Codex)",         "40.80"],
    ["AGENTIC",   "MCP Atlas (Tool Use)",             "Muse Spark", "Muse Spark",                    "78.30"],
    ["AGENTIC",   "SWE-Bench Pro (Public)",           "OpenAI",     "GPT-5.4-pro (xHigh)",           "59.10"],
    ["AGENTIC",   "SWE-Bench Pro (Private)",          "Anthropic",  "Claude Opus 4.6",               "47.10"],
    ["FRONTIER",  "Humanity's Last Exam",             "OpenAI",     "GPT-5.4-pro",                   "44.32"],
    ["FRONTIER",  "EnigmaEval",                       "OpenAI",     "GPT-5.4-pro",                   "23.82"],
    ["FRONTIER",  "MultiChallenge",                   "Muse Spark", "Muse Spark",                    "75.52"],
    ["FRONTIER",  "SciPredict",                       "Google",     "Gemini-3-pro-preview",          "25.27"],
    ["SAFETY",    "MASK (Honesty)",                   "Anthropic",  "Claude Opus 4.6",               "96.28"],
    ["SAFETY",    "Professional Reasoning – Legal",   "Anthropic",  "Claude Opus 4.6",               "52.27"],
    ["SAFETY",    "Professional Reasoning – Finance", "Anthropic",  "Claude Opus 4.6",               "53.28"],
    ["MULTIMODAL","AudioMultiChallenge (Text Output)","Google",     "Gemini-3-pro-preview",          "54.65"],
    ["MULTIMODAL","AudioMultiChallenge (Audio Output)","Google",    "Gemini-3.1-flash-live",         "36.06"],
    ["MULTIMODAL","VISTA Vision-Language",            "Google",     "Gemini 2.5 Pro Exp",            "54.65"],
    ["MULTIMODAL","VisualToolBench",                  "OpenAI",     "GPT-5.4",                       "29.17"],
  ];

  // Domain colors
  const domainFills = {
    "AGENTIC":    "E8F5F0",
    "FRONTIER":   "EBF3FE",
    "SAFETY":     "FFF3EE",
    "MULTIMODAL": "F0F0FF",
  };

  const hdrRow = [
    { text: "Domain",    options: { bold: true, color: C.white, fill: { color: C.navy }, align: "center" } },
    { text: "Benchmark", options: { bold: true, color: C.white, fill: { color: C.navy }, align: "left" } },
    { text: "#1 Lab",    options: { bold: true, color: C.white, fill: { color: C.navy }, align: "center" } },
    { text: "#1 Model",  options: { bold: true, color: C.white, fill: { color: C.navy }, align: "left" } },
    { text: "Score",     options: { bold: true, color: C.white, fill: { color: C.navy }, align: "center" } },
  ];

  const tableRows = matrixData.map(([domain, bench, lab, model, score]) => {
    const lc = labColors[lab] || { fill: "F8FAFD", text: C.darkTxt };
    const df = domainFills[domain] || "F8FAFD";
    return [
      { text: domain,  options: { bold: true, fontSize: 9, color: C.midTxt, fill: { color: df }, align: "center" } },
      { text: bench,   options: { fontSize: 9.5, color: C.darkTxt, fill: { color: C.white }, align: "left" } },
      { text: lab,     options: { bold: true, fontSize: 9.5, color: lc.text, fill: { color: lc.fill }, align: "center" } },
      { text: model,   options: { fontSize: 9, color: C.midTxt, fill: { color: C.white }, align: "left" } },
      { text: score,   options: { bold: true, fontSize: 10, color: lc.text, fill: { color: lc.fill }, align: "center" } },
    ];
  });

  s.addTable([hdrRow, ...tableRows], {
    x: 0.28, y: 1.22, w: 9.44, h: 4.05,
    colW: [1.15, 2.8, 1.25, 3.0, 0.9],
