    rowH: 0.225,
    fontFace: BODY_FONT,
    valign: "middle",
  });

  // Lab legend
  const legendLabs = [["OpenAI", C.openai], ["Google", C.google], ["Anthropic", C.anthro], ["Muse Spark", C.muse]];
  legendLabs.forEach(([name, col], i) => {
    const lx = 0.28 + i * 1.55;
    s.addShape(pres.shapes.RECTANGLE, {
      x: lx, y: 5.27, w: 1.42, h: 0.23,
      fill: { color: col },
      line: { color: col, width: 0 },
    });
    s.addText(name, {
      x: lx, y: 5.27, w: 1.42, h: 0.23,
      fontFace: BODY_FONT, fontSize: 8.5, bold: true, color: C.white,
      align: "center", valign: "middle", margin: 0,
    });
  });
}

// ═══════════════════════════════════════════════════════════════════
