  s.addText("KEY TAKEAWAYS", {
    x: 0.5, y: 0.3, w: 6.2, h: 0.35,
    fontFace: TITLE_FONT, fontSize: 10, bold: true,
    color: C.accent, align: "left", charSpacing: 3, margin: 0,
  });
  s.addText("No Single Model Wins Everything —\nSpecialization Is the New Frontier", {
    x: 0.5, y: 0.72, w: 6.3, h: 1.1,
    fontFace: TITLE_FONT, fontSize: 26, bold: true, color: C.white,
    align: "left", valign: "top", margin: 0,
  });

  const findings = [
    {
      num: "01",
      color: C.openai,
      lab: "OpenAI",
      text: "GPT-5.4 leads agentic coding (SWE Atlas, SWE-Bench Pro Public) and frontier reasoning (HLE at 44.3%, EnigmaEval at 23.8%) — but not multimodal.",
    },
    {
      num: "02",
      color: C.google,
      lab: "Google",
      text: "Gemini sweeps audio benchmarks — all top-3 on AudioMultiChallenge (Text Output) are Gemini variants. Leads VISTA vision-language at 54.65.",
    },
    {
      num: "03",
      color: C.anthro,
      lab: "Anthropic",
      text: "Claude leads safety & honesty: 96.28% on MASK (#1), plus both Professional Reasoning benchmarks (Legal 52.27, Finance 53.28).",
    },
    {
      num: "04",
      color: C.amber,
      lab: "Unsaturated",
      text: "Frontier benchmarks remain wide open: HLE 44%, EnigmaEval 24%, SciPredict 25% — significant room for improvement across all labs.",
    },
    {
      num: "05",
      color: C.muse,
      lab: "Muse Spark",
      text: "New entrant Muse Spark ranks top-3 on 6+ benchmarks: #1 MultiChallenge (75.5%), #1 MCP Atlas (78.3%), top-3 in SWE-Bench Pro and HLE.",
    },
  ];

  findings.forEach((f, i) => {
    const fy = 1.95 + i * 0.64;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.42, y: fy, w: 0.42, h: 0.46,
      fill: { color: f.color },
      line: { color: f.color, width: 0 },
    });
    s.addText(f.num, {
      x: 0.42, y: fy, w: 0.42, h: 0.46,
      fontFace: TITLE_FONT, fontSize: 12, bold: true, color: C.white,
      align: "center", valign: "middle", margin: 0,
    });
    s.addText(f.text, {
      x: 0.94, y: fy, w: 5.82, h: 0.46,
      fontFace: BODY_FONT, fontSize: 11, color: "CBD5E1",
      align: "left", valign: "middle", margin: 0,
    });
  });

  // Right panel summary stats
  const stats = [
    ["20+", "Benchmarks"],
    ["100+", "Models"],
    ["4", "Domains"],
    ["6+", "Muse Spark Top-3"],
  ];
  stats.forEach(([num, label], i) => {
    const sy = 0.85 + i * 1.16;
    s.addText(num, {
      x: 7.1, y: sy, w: 2.75, h: 0.65,
      fontFace: TITLE_FONT, fontSize: 36, bold: true, color: C.accent,
      align: "center", valign: "middle", margin: 0,
    });
    s.addText(label, {
      x: 7.1, y: sy + 0.65, w: 2.75, h: 0.3,
      fontFace: BODY_FONT, fontSize: 11, color: C.slate2,
      align: "center", valign: "top", margin: 0,
    });
  });

  s.addText("scale.com/leaderboard", {
    x: 7.1, y: 5.28, w: 2.75, h: 0.24,
    fontFace: BODY_FONT, fontSize: 9.5, color: C.accent,
    align: "center", margin: 0,
  });
}

// ── Write file ───────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
